; slow.asm -- chapter 14: a wait worked out from Zilog's table
; generated by gen14.py
        INCLUDE "msx.inc"
        OUTPUT "slow.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; WHERE IT BREAKS. A wait of one 50 Hz frame, 71,364 T-states, worked out
; from Zilog's table: 10 for LD DE,nn, 26 a turn and 5 less for the last,
; 7 for LD C,0 and 4 for a NOP. Then 256 NOPs and a RET, called: 1,051 by
; the same table. meas14.py times both on the MSX.
init:   di
        ld sp, SYS_AREA
s1:     ld de, 2744
wz:     dec de
        ld a, d
        or e
        jr nz, wz
        ld c, 0
        nop
        nop
s2:     call nops
s3:     nop
stop:   jr stop

nops:   DUP 256                 ; sjasmplus writes the next line 256 times
        nop
        EDUP
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
